<?php declare(strict_types=1); namespace App\Models; use Illuminate\Database\Eloquent\Model; class PreauthBlock extends Model { protected $guarded=[]; protected $casts=["amount_cents"=>"integer","blocked_at"=>"datetime","released_at"=>"datetime"]; public function reservation(){return $this->belongsTo(Reservation::class);} public function hotel(){return $this->belongsTo(Hotel::class);} public function releaser(){return $this->belongsTo(User::class,"released_by");} }